// 版本策略对比：URL 版本 vs Header/媒体类型版本（同一路由表，两种解析器）
const routes = [
  { version: 'v1', method: 'GET',  pattern: '/articles',     handler: 'v1.listArticles' },
  { version: 'v1', method: 'GET',  pattern: '/articles/:id', handler: 'v1.getArticle' },
  { version: 'v1', method: 'POST', pattern: '/articles',     handler: 'v1.createArticle' },
  { version: 'v2', method: 'GET',  pattern: '/articles',     handler: 'v2.listArticles' },
  { version: 'v2', method: 'GET',  pattern: '/articles/:id', handler: 'v2.getArticle' },
];

function matchPath(pattern, path) {
  const keys = [];
  const rx = new RegExp('^' + pattern.replace(/:(\w+)/g, function (_, k) { keys.push(k); return '([^/]+)'; }) + '$');
  const m = rx.exec(path);
  if (!m) return null;
  const params = {};
  keys.forEach(function (k, i) { params[k] = m[i + 1]; });
  return params;
}

function lookup(version, method, path) {
  for (const r of routes) {
    if (r.version !== version || r.method !== method) continue;
    const params = matchPath(r.pattern, path);
    if (params) return { handler: r.handler, params };
  }
  return null;
}

// 策略 A：版本在路径里
function resolveUrl(versionedPath) {
  const m = /^\/v(\d+)(\/.*)?$/.exec(versionedPath);
  if (!m) return { strategy: 'url', version: null, handler: null, params: null, cacheKey: versionedPath, note: 'no /vN prefix' };
  const version = 'v' + m[1];
  const rest = m[2] || '/';
  const hit = lookup(version, 'GET', rest);
  return { strategy: 'url', version: version, handler: hit && hit.handler,
           params: (hit && hit.params) || null, cacheKey: versionedPath,
           note: hit ? 'matched' : 'no such route in ' + version };
}

// 策略 B：版本在 Accept 媒体类型（或 API-Version 头）里，路径不含版本
function resolveHeader(path, headers) {
  const accept = headers.accept || '';
  const m = /application\/vnd\.articles\.v(\d+)\+json/.exec(accept);
  const version = m ? 'v' + m[1] : (headers['api-version'] || 'v1');
  const hit = lookup(version, 'GET', path);
  return { strategy: 'header', version: version, handler: hit && hit.handler,
           params: (hit && hit.params) || null, cacheKey: path,
           note: hit ? 'matched' : 'no such route in ' + version };
}

const requests = [
  ['/v1/articles', {}],
  ['/v1/articles/9', {}],
  ['/v3/articles', {}],
  ['/articles', { accept: 'application/vnd.articles.v2+json' }],
  ['/articles/9', { accept: 'application/vnd.articles.v2+json' }],
  ['/articles', {}],
  ['/articles/9', { 'api-version': 'v9' }],
];

for (const pair of requests) {
  const path = pair[0];
  const headers = pair[1];
  const a = resolveUrl(path);
  const b = resolveHeader(path.replace(/^\/v\d+/, '') || '/', headers);
  console.log('request GET ' + path + ' headers=' + JSON.stringify(headers));
  console.log('  url_strategy    version=' + (a.version || '-') + ' handler=' + (a.handler || '-')
    + ' params=' + JSON.stringify(a.params) + ' cache_key=' + a.cacheKey + ' note=' + a.note);
  console.log('  header_strategy version=' + b.version + ' handler=' + (b.handler || '-')
    + ' params=' + JSON.stringify(b.params) + ' cache_key=' + b.cacheKey + ' note=' + b.note);
}

